<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";

const PROFILE =
  "http://ihris.org/fhir/StructureDefinition/staffs-exchange-locations-profile";
const REVIEW_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/review-staff-exchange-location-profile";

// Statuses a staff member may still withdraw from. Mirrors
// cancelStaffExchangeLocationWorkflow.js - everything from "psapproved"
// onward is excluded because the PS has already decided and the District
// HOD apply step may be part-done.
const CANCELLABLE_STATUSES = [
  "pending",
  "undersupervisorreview",
  "underdistricthrreview",
  "underdistricthodreview",
  "underhrdirectorreview",
  "underdepartmentaldirreview",
  "underpsreview",
];

// Maps a request's own status code to the base code of whichever timeline
// stage is currently pending a decision on it.
const STATUS_STAGE_MAP = {
  undersupervisorreview: "supervisor",
  underdistricthrreview: "districthr",
  underdistricthodreview: "districthod",
  // Parked mid-handshake - the exchange is still AT that stage,
  // just waiting on the counterpart reviewer to act.
  awaitingpartnersupervisor: "supervisor",
  awaitingpartnerdistricthr: "districthr",
  awaitingpartnerdistricthod: "districthod",
  underhrdirectorreview: "directorhr",
  underdepartmentaldirreview: "departmentaldir",
  underpsreview: "ps",
  psapproved: "districthodapply",
  hodapplied: "districthodapply",
};

export default {
  name: "StaffExchangeView",
  mixins: [generalMixin, processQuestionnaire],
  props: ["queries"],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/cancel-staff-exchange-location",
      fhir: {},
      profile: PROFILE,

      loading: true,
      error: null,

      isParty: false,
      // Only the staff member who raised this request may withdraw it -
      // being a party to the exchange is not enough.
      isRequester: false,

      cancelDialog: false,
      cancelling: false,
      cancelSubmitted: false,
      cancelReason: "",
      // Populated when the request is already cancelled, so the page can
      // say who actually withdrew rather than implying it was this viewer.
      cancellation: { byRef: null, byName: "", reason: "", date: null },

      snackbar: { show: false, text: "", color: "success" },

      requesterName: "",
      partnerName: "",
      cancelledByName: "",

      exchange: {
        plannedTransferDate: null,
        transferReason: "",
        status: null,
        statusDisplay: "Pending",
        eventDate: null,
      },
      // The partner's OWN exchange request - only id/status are needed
      // (name/dates are already covered by exchange/partnerName above).
      partnerExchange: {
        id: null,
        status: null,
      },

      currentPosition: {},
      destinationPosition: {},
      // Partner's own current position - loaded solely to resolve the
      // shared-reviewer coverage checks below, not rendered directly.
      partnerCurrentPosition: {},

      reviews: [],

      // null while unresolved. Whether the SAME District HR/HOD officer
      // actually covers both staff members' facilities — resolved via
      // /site/general/getHR and /getHOD (the same coverage-aware lookup
      // the backend workflows use), NOT a plain admin-district-id
      // comparison.
      sameDistrictHR: null,
      sameDistrictHOD: null,
    };
  },

  computed: {
    backLabel() {
      return (this.queries && this.queries.returnLabel) || "Back";
    },

    initials() {
      if (!this.requesterName) return "?";
      return this.requesterName
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },

    // Info-banner copy for the district-stage section, driven by the
    // resolved sameDistrictHR/sameDistrictHOD coverage flags.
    districtStageBannerText() {
      if (this.sameDistrictHR === null || this.sameDistrictHOD === null) {
        return "Checking whether both staff members share the same District HR/HOD coverage…";
      }
      if (this.sameDistrictHR && this.sameDistrictHOD) {
        return "Same District HR and HOD coverage — District HR and District HOD review both requests in one combined action.";
      }
      if (!this.sameDistrictHR && !this.sameDistrictHOD) {
        return "Different District HR and HOD coverage — each staff member is reviewed independently at the District HR and HOD stages.";
      }
      return `District HR review is ${
        this.sameDistrictHR ? "combined" : "independent per staff member"
      }; District HOD review is ${
        this.sameDistrictHOD ? "combined" : "independent per staff member"
      } — their facility coverage differs at only one of the two stages.`;
    },

    // Supervisor is always per-staff, regardless of district. District
    // HR/HOD collapse into a single combined stage when the two staff
    // share a district, and split into two independent stages when they
    // don't. Departmental Director, HR Director and PS are always
    // combined, regardless of district.
    timeline() {
      const findReview = (code, requestId) =>
        this.reviews.find(
          (r) =>
            r.reviewerCode === code &&
            r.requestId === requestId &&
            r.status !== "applied",
        ) || null;
      // The Apply stage (after PS approval) reuses the SAME reviewer code
      // ("districthod") as the District HOD review stage earlier in the
      // pipeline - it's genuinely the same reviewer, just a different
      // action, so review-status ("applied" vs approved/rejected) is what
      // distinguishes the two, not the reviewer code.
      const findAppliedReview = (requestId) =>
        this.reviews.find(
          (r) =>
            r.reviewerCode === "districthod" &&
            r.requestId === requestId &&
            r.status === "applied",
        ) || null;

      const stages = [
        {
          code: "supervisor-mine",
          label: `Supervisor of ${this.requesterName || "This staff member"}`,
          review: findReview("supervisor", this.queries.id),
        },
        {
          code: "supervisor-partner",
          label: `Supervisor of ${this.partnerName || "Exchange partner"}`,
          review: findReview("supervisor", this.partnerExchange.id),
        },
      ];

      const districtStages = [
        {
          code: "districthr",
          label: "District HR",
          combined: this.sameDistrictHR,
        },
        {
          code: "districthod",
          label: "District HOD",
          combined: this.sameDistrictHOD,
        },
      ];

      for (const stage of districtStages) {
        if (stage.combined) {
          stages.push({
            code: stage.code,
            label: `${stage.label} — Combined Review`,
            review: findReview(stage.code, this.queries.id),
          });
        } else {
          stages.push({
            code: stage.code + "-mine",
            label: `${stage.label} of ${this.requesterName ||
              "This staff member"}`,
            review: findReview(stage.code, this.queries.id),
          });
          stages.push({
            code: stage.code + "-partner",
            label: `${stage.label} of ${this.partnerName ||
              "Exchange partner"}`,
            review: findReview(stage.code, this.partnerExchange.id),
          });
        }
      }

      const combinedStages = [
        { code: "directorhr", label: "HR Director" },
        { code: "departmentaldir", label: "Departmental Director" },
        { code: "ps", label: "PS" },
      ];
      for (const stage of combinedStages) {
        stages.push({
          code: stage.code,
          label: `${stage.label} — Combined Review`,
          review: findReview(stage.code, this.queries.id),
        });
      }

      // District HOD Apply - the finalization step after PS approval.
      // Combined-vs-independent here is mathematically the SAME
      // determination as sameDistrictHOD above: the backend's own
      // sharedReviewer check for this stage compares whether the same HOD
      // covers each staff's DESTINATION facility, but a swap only ever
      // involves this exact pair of facilities (my destination = partner's
      // origin, and vice versa) - "do the destinations share an HOD" and
      // "do the origins share an HOD" are the same boolean either way, so
      // sameDistrictHOD is reused directly rather than resolving it again.
      if (this.sameDistrictHOD) {
        stages.push({
          code: "districthodapply",
          label: "District HOD — Apply Transfer (Combined)",
          review: findAppliedReview(this.queries.id),
        });
      } else {
        stages.push({
          code: "districthodapply-mine",
          label: `District HOD — Apply Transfer of ${this.requesterName ||
            "This staff member"}`,
          review: findAppliedReview(this.queries.id),
        });
        stages.push({
          code: "districthodapply-partner",
          label: `District HOD — Apply Transfer of ${this.partnerName ||
            "Exchange partner"}`,
          review: findAppliedReview(this.partnerExchange.id),
        });
      }

      return stages;
    },

    // Withdrawing ends the whole exchange, so it is restricted to the
    // staff member who raised this request - the partner withdraws via
    // their own request, not this one.
    canCancel() {
      return (
        this.isRequester && CANCELLABLE_STATUSES.includes(this.exchange.status)
      );
    },

    // True when the viewer is the one who withdrew. Drives the wording so
    // a partner never reads "You cancelled" about someone else's decision.
    cancelledByMe() {
      const mine = this.loggedInStaff?.practitioner;
      const by = this.cancellation.byRef;
      return !!mine && !!by && this.refId(by) === String(mine);
    },

    // Names the reviewer role this request is parked behind, or null when
    // it is not mid-handshake. Drives the banner that used to wrongly say
    // "waiting for your partner to submit a request".
    parkedStage() {
      return (
        {
          awaitingpartnersupervisor: "supervisor",
          awaitingpartnerdistricthr: "District HR",
          awaitingpartnerdistricthod: "District HOD",
        }[this.exchange.status] || null
      );
    },

    myCurrentStageCode() {
      return STATUS_STAGE_MAP[this.exchange.status] || null;
    },

    partnerCurrentStageCode() {
      return STATUS_STAGE_MAP[this.partnerExchange.status] || null;
    },
  },

  async created() {
    if (!this.queries || !this.queries.id) {
      this.error = "No exchange request specified.";
      this.loading = false;
      return;
    }

    await this.loadRequest();
  },

  methods: {
    // Extension urls come from the *Extension definition's* id, not the FSH
    // slice name — try the canonical id(s) first, fall back to the slice
    // name in case the upstream IG source is corrected later.
    getExt(resource, urlParts) {
      const candidates = Array.isArray(urlParts) ? urlParts : [urlParts];
      const exts = resource.extension || [];
      for (const part of candidates) {
        const found = exts.find((e) => e.url.includes(part));
        if (found) return found;
      }
      return null;
    },

    async loadRequest() {
      this.loading = true;
      this.error = null;

      try {
        const response = await fetch(`/fhir/Basic/${this.queries.id}`);
        if (!response.ok) {
          throw new Error("Exchange request not found");
        }

        const resource = await response.json();
        if (!resource.meta?.profile?.includes(PROFILE)) {
          throw new Error("Resource is not a staff exchange request");
        }

        // Wait for generalMixin to finish loading loggedInStaff
        await new Promise((resolve) => {
          if (!this.loadingUserData) {
            resolve();
            return;
          }
          const unwatch = this.$watch("loadingUserData", (newValue) => {
            if (!newValue) {
              unwatch();
              resolve();
            }
          });
          setTimeout(() => {
            unwatch();
            resolve();
          }, 15000);
        });

        const requesterRef = this.getExt(resource, [
          "ihris-practitioner-reference",
          "practitioner",
        ])?.valueReference?.reference;
        const partnerRef = this.getExt(resource, "staff-exchanging-with")
          ?.valueReference?.reference;

        const myPractitionerRef = this.loggedInStaff?.practitioner
          ? "Practitioner/" + this.loggedInStaff.practitioner
          : null;
        this.isParty =
          !!myPractitionerRef &&
          (requesterRef === myPractitionerRef ||
            partnerRef === myPractitionerRef);
        this.isRequester =
          !!myPractitionerRef && requesterRef === myPractitionerRef;
        if (!this.isParty) {
          this.loading = false;
          return;
        }

        this.cancellation = {
          byRef: this.getExt(resource, "cancelled-by")?.valueReference
            ?.reference,
          byName: "",
          reason: this.getExt(resource, "cancel-reason")?.valueString || "",
          date: this.getExt(resource, "cancel-date")?.valueDate,
        };
        if (this.cancellation.byRef) {
          this.loadPractitionerName(this.cancellation.byRef, "cancelledByName");
        }

        const statusCoding = this.getExt(resource, ["request-status", "status"])
          ?.valueCoding;

        this.exchange = {
          plannedTransferDate: this.getExt(resource, "planned-transfer-date")
            ?.valueDate,
          transferReason: this.getExt(resource, ["reason", "transfer-reason"])
            ?.valueString,
          status: statusCoding?.code || null,
          statusDisplay: statusCoding?.display || "Pending",
          eventDate:
            this.getExt(resource, "event-date")?.valueDate ||
            resource.meta?.lastUpdated,
        };

        const curExt = this.getExt(resource, [
          "position-reference",
          "current-position",
        ]);
        const destExt = this.getExt(resource, [
          "destination-position",
          "destition-position",
        ]);
        const curRef = curExt?.valueReference?.reference;
        const destRef = destExt?.valueReference?.reference;

        await Promise.all([
          this.loadPractitionerName(requesterRef, "requesterName"),
          this.loadPractitionerName(partnerRef, "partnerName"),
          this.loadPosition(
            curRef,
            "currentPosition",
            curExt?.valueReference?.display,
          ),
          this.loadPosition(
            destRef,
            "destinationPosition",
            destExt?.valueReference?.display,
          ),
          this.loadPartnerExchange(requesterRef, partnerRef),
        ]);

        // Needs both request ids resolved first (partnerExchange.id comes
        // out of loadPartnerExchange above), so it runs after the
        // Promise.all rather than inside it.
        await this.loadReviews();

        if (this.partnerExchange.id) {
          await Promise.all([
            this.resolveSharedReviewer("HR").then(
              (shared) => (this.sameDistrictHR = shared),
            ),
            this.resolveSharedReviewer("HOD").then(
              (shared) => (this.sameDistrictHOD = shared),
            ),
          ]);
        }
      } catch (err) {
        console.error("Error loading exchange request:", err);
        this.error = err.message || "Failed to load exchange request details";
      } finally {
        this.loading = false;
      }
    },

    async loadPractitionerName(ref, target) {
      if (!ref) return;
      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Practitioner/${id}?_elements=name`);
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this[target] = name
          ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this[target] = "Unknown";
      }
    },

    refId(ref) {
      if (!ref) return null;
      return ref.includes("/") ? ref.split("/")[1] : ref;
    },

    // Resolves the partner's OWN exchange request (their id, status and
    // current position) — needed for the review timeline, which has to
    // track both sides' progress independently once a district stage
    // splits. Explicitly fetched rather than inferred from "my destination
    // position" (which happens to describe the same facility, but isn't
    // guaranteed to be the exact same Position record).
    async loadPartnerExchange(requesterRef, partnerRef) {
      if (!requesterRef || !partnerRef) return;
      try {
        const params = new URLSearchParams({
          _profile: PROFILE,
          practitioner: partnerRef,
          staffexchanginglocation: requesterRef,
          _sort: "-eventdate",
          _count: 1,
        });
        const res = await fetch(`/fhir/Basic?${params}`);
        const bundle = await res.json();
        const resource = bundle.entry?.[0]?.resource;
        if (!resource) return;

        const statusCoding = this.getExt(resource, ["request-status", "status"])
          ?.valueCoding;
        this.partnerExchange.id = resource.id;
        this.partnerExchange.status = statusCoding?.code || null;

        const curExt = this.getExt(resource, [
          "position-reference",
          "current-position",
        ]);
        this.partnerCurrentPosition = await this.loadPositionData(
          curExt?.valueReference?.reference,
          curExt?.valueReference?.display,
        );
      } catch (err) {
        console.error("loadPartnerExchange error:", err);
      }
    },

    // Same lookup as loadPosition(), but returns the result instead of
    // assigning it to a data property — used for the partner's position,
    // which isn't rendered on this page, only needed for the shared-
    // reviewer coverage check.
    async loadPositionData(ref, fallbackDisplay) {
      const target = "__tmpPosition";
      await this.loadPosition(ref, target, fallbackDisplay);
      const result = this[target];
      delete this[target];
      return result || { designation: fallbackDisplay || "" };
    },

    // Fetches every review touching either side of this exchange (mine or
    // the partner's request) so the timeline can show both, however the
    // same/different-district split shapes it. There's no dedicated search
    // param for staff-exchange-location-reference, so this filters
    // client-side — same approach used elsewhere in this feature.
    async loadReviews() {
      try {
        const wantedIds = [this.queries.id, this.partnerExchange.id].filter(
          Boolean,
        );
        if (!wantedIds.length) return;

        const res = await fetch(
          `/fhir/Basic?_profile=${REVIEW_PROFILE}&_count=200`,
        );
        const bundle = await res.json();
        const resources = (bundle.entry || []).map((e) => e.resource);

        const matches = [];
        for (const r of resources) {
          const refs = (r.extension || [])
            .filter((e) => e.url.includes("staff-exchange-location-reference"))
            .map((e) => e.valueReference?.reference);
          const requestId = wantedIds
            .map((id) => "Basic/" + id)
            .find((ref) => refs.includes(ref));
          if (!requestId) continue;
          matches.push({ resource: r, requestId: this.refId(requestId) });
        }

        const reviewerRefs = [
          ...new Set(
            matches
              .map(
                (m) =>
                  this.getExt(m.resource, [
                    "ihris-practitioner-reference",
                    "practitioner",
                  ])?.valueReference?.reference,
              )
              .filter(Boolean),
          ),
        ];
        const nameMap = {};
        await Promise.all(
          reviewerRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              nameMap[ref] = name
                ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
                : ref;
            } catch {
              nameMap[ref] = ref;
            }
          }),
        );

        this.reviews = matches.map(({ resource: r, requestId }) => {
          const reviewerRef = this.getExt(r, [
            "ihris-practitioner-reference",
            "practitioner",
          ])?.valueReference?.reference;
          const statusCoding = this.getExt(r, ["review-status", "status"])
            ?.valueCoding;
          return {
            id: r.id,
            requestId,
            reviewerCode: this.getExt(r, "reviewer")?.valueCoding?.code,
            reviewerName: nameMap[reviewerRef] || "Unknown",
            status: statusCoding?.code || null,
            statusDisplay: statusCoding?.display || "Pending",
            comments: this.getExt(r, "comments")?.valueString || "",
            date: this.getExt(r, ["date", "review-date"])?.valueDate,
          };
        });
      } catch (err) {
        console.error("loadReviews error:", err);
      }
    },

    // Resolves whether the SAME District HR ("HR") or District HOD ("HOD")
    // officer(s) cover BOTH staff members' current facility/department —
    // the same coverage lookup (/site/general/getHR, /getHOD) the backend
    // workflows use, rather than a plain admin-district-id comparison.
    async resolveSharedReviewer(kind) {
      const mine = this.currentPosition;
      const theirs = this.partnerCurrentPosition;
      if (!mine?.facilityId || !mine?.districtId) return null;
      if (!theirs?.facilityId || !theirs?.districtId) return null;

      const endpoint = kind === "HOD" ? "getHOD" : "getHR";
      const buildParams = (pos) => {
        const params = new URLSearchParams({
          district: pos.districtId,
          facility: pos.facilityId,
        });
        if (kind === "HOD") params.set("department", pos.departmentCode || "");
        return params;
      };

      try {
        const [resA, resB] = await Promise.all([
          fetch(`/site/general/${endpoint}?${buildParams(mine)}`),
          fetch(`/site/general/${endpoint}?${buildParams(theirs)}`),
        ]);
        if (!resA.ok || !resB.ok) return null;
        const [dataA, dataB] = await Promise.all([resA.json(), resB.json()]);
        const practitionersA = (Array.isArray(dataA) ? dataA : []).flatMap(
          (h) => h.practitioners || [],
        );
        const practitionersB = (Array.isArray(dataB) ? dataB : []).flatMap(
          (h) => h.practitioners || [],
        );
        return practitionersA.some((p) => practitionersB.includes(p));
      } catch (error) {
        console.error(`Error resolving shared ${kind}:`, error);
        return null;
      }
    },

    // A stage is "current" if its base code matches the CURRENT status of
    // the request it actually belongs to - see myCurrentStageCode/
    // partnerCurrentStageCode computed.
    isCurrentStage(stage) {
      if (stage.code.endsWith("-mine")) {
        const base = stage.code.slice(0, -"-mine".length);
        return this.myCurrentStageCode === base;
      }
      if (stage.code.endsWith("-partner")) {
        const base = stage.code.slice(0, -"-partner".length);
        return this.partnerCurrentStageCode === base;
      }
      return this.myCurrentStageCode === stage.code;
    },

    // Walk Location.partOf up the hierarchy (facility → council → district)
    // until a Location tagged with the district profile is found. Returns
    // { name, id } - the id is needed to compare "same district" reliably
    // (matches how the backend workflows compare district.id).
    async resolveDistrict(facilityRef) {
      try {
        let ref = facilityRef;
        for (let i = 0; i < 5 && ref; i++) {
          const id = this.refId(ref);
          if (!id) return { name: "", id: null };
          const res = await fetch(`/fhir/Location/${id}`);
          if (!res.ok) return { name: "", id: null };
          const loc = await res.json();
          if (loc.meta?.profile?.some((p) => p.includes("ls-district"))) {
            return { name: loc.name || "", id: loc.id };
          }
          ref = loc.partOf?.reference;
        }
        return { name: "", id: null };
      } catch (error) {
        console.error("Error resolving district:", error);
        return { name: "", id: null };
      }
    },

    async loadPosition(ref, target, fallbackDisplay) {
      this[target] = { designation: fallbackDisplay || "", loadError: null };
      if (!ref) return;

      try {
        const id = this.refId(ref);
        if (!id) return;
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) {
          this[target] = {
            ...this[target],
            loadError: `Could not load position ${ref} (HTTP ${response.status})`,
          };
          return;
        }
        const position = await response.json();
        if (!position.extension?.length) {
          this[target] = {
            ...this[target],
            loadError: `${ref} has no position data on it`,
          };
          return;
        }
        const getExt = (part, type) => {
          const ext = position.extension?.find((e) => e.url.includes(part));
          return ext ? ext[type] : null;
        };

        let designation = fallbackDisplay || "";
        const designationRef = getExt("designation", "valueReference")
          ?.reference;
        if (designationRef) {
          try {
            const dId = this.refId(designationRef);
            const dRes = await fetch(`/fhir/Basic/${dId}`);
            const dData = await dRes.json();
            designation =
              dData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || designation;
          } catch {
            // designation lookup best-effort
          }
        }

        let facility = "";
        let district = "";
        let districtId = null;
        let facilityId = null;
        const facilityRef = getExt("facility", "valueReference")?.reference;
        if (facilityRef) {
          facilityId = this.refId(facilityRef);
          try {
            const fRes = await fetch(`/fhir/Location/${facilityId}`);
            const fData = await fRes.json();
            facility = fData.name || "";
          } catch {
            // facility lookup best-effort
          }
          const resolved = await this.resolveDistrict(facilityRef);
          district = resolved.name;
          districtId = resolved.id;
        }

        this[target] = {
          designation,
          department: getExt("department", "valueCoding")?.display || "",
          departmentCode: getExt("department", "valueCoding")?.code || null,
          facility,
          facilityId,
          district,
          districtId,
        };
      } catch (error) {
        console.error("Error loading position:", error);
      }
    },

    statusKey(status) {
      if (!status) return "warn";
      if (status === "approved") return "done";
      if (status && status.includes("rejected")) return "error";
      if (status === "cancelled") return "none";
      if (status && status.includes("review")) return "active";
      return "warn";
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "N/A";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },

    openCancelDialog() {
      this.cancelSubmitted = false;
      this.cancelReason = "";
      this.cancelDialog = true;
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    // Backend contract: POST /fhir/QuestionnaireResponse routed via the
    // "cancel-staff-exchange-location" Questionnaire to
    // cancelStaffExchangeLocationWorkflow.js, with this.fhir = {
    //   request: "<this exchange request Basic id>",
    //   cancelReason: string (>= 20 chars),
    //   date: "YYYY-MM-DD",
    // }
    // The workflow cancels BOTH halves of the exchange and notifies the
    // partner - this page only ever submits its own request id.
    async cancelExchange() {
      this.cancelSubmitted = true;
      if (!this.cancelReason || this.cancelReason.trim().length < 20) {
        this.showSnackbar(
          "Please give a reason of at least 20 characters.",
          "error",
        );
        return;
      }

      this.cancelling = true;
      try {
        this.fhir = {
          request: this.queries.id,
          cancelReason: this.cancelReason.trim(),
          date: new Date().toISOString().substr(0, 10),
        };
        this.afterSaveMessage = "Exchange request cancelled.";
        await this.processFHIR();
        this.cancelDialog = false;
        this.showSnackbar(this.afterSaveMessage, "success");
        await this.loadRequest();
      } catch (err) {
        console.error("cancelExchange error:", err);
        this.showSnackbar(
          "Failed to cancel the request. Please try again.",
          "error",
        );
      } finally {
        this.cancelling = false;
      }
    },

    goBack() {
      if (this.queries && this.queries.returnPath) {
        this.$router.push({
          path: this.queries.returnPath,
          query: this.queries.returnQuery
            ? JSON.parse(this.queries.returnQuery)
            : undefined,
        });
      } else if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    scrollTo(section) {
      const el = document.getElementById("section-" + section);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },
  },
};
</script>

